import json
import os
import sys

BASE = "/Users/kristinarash/Library/Caches/sportsci-batch-123"
IDS = ["Q41", "Q42", "Q43", "Q44", "Q45", "Q46", "Q47", "Q48"]
REQUIRED = [
    "id", "sourceFile", "decision", "exclusionReason", "degradedReason", "doiMissing",
    "identityCheck", "confidence", "studyDesign", "primaryDomain", "domains", "audiences",
    "sports", "populations", "evidenceSummary", "screeningLimitations", "synthesisCaution", "paper",
]
PAPER_KEYS = ["year", "citation", "doi", "abstract", "tldr", "methods", "findings",
              "limitations", "practicalImplications", "athleteDev", "rtp"]

tax = json.load(open(os.path.join(BASE, "taxonomy.json")))
inputs = {it["id"]: it for it in json.load(open(os.path.join(BASE, "inputs.json")))}

problems = []


def walk_strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for v in obj.values():
            yield from walk_strings(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from walk_strings(v)


for pid in IDS:
    path = os.path.join(BASE, "drafts", pid + ".json")
    if not os.path.exists(path):
        problems.append(f"{pid}: missing draft")
        continue
    d = json.load(open(path, encoding="utf-8"))
    inp = inputs[pid]
    for k in REQUIRED:
        if k not in d:
            problems.append(f"{pid}: missing key {k}")
    if d.get("id") != pid:
        problems.append(f"{pid}: id mismatch")
    if d.get("sourceFile") != inp["sourceFile"]:
        problems.append(f"{pid}: sourceFile mismatch -> {d.get('sourceFile')!r} vs {inp['sourceFile']!r}")
    if d.get("decision") not in ("INCLUDE", "EXCLUDE", "DEGRADED"):
        problems.append(f"{pid}: bad decision")
    if d.get("studyDesign") not in tax["studyDesigns"]:
        problems.append(f"{pid}: bad studyDesign {d.get('studyDesign')!r}")
    if d.get("primaryDomain") not in tax["domains"]:
        problems.append(f"{pid}: bad primaryDomain")
    if d.get("primaryDomain") not in d.get("domains", []):
        problems.append(f"{pid}: primaryDomain not in domains")
    for field, vocab in (("domains", "domains"), ("audiences", "audiences"),
                         ("sports", "sports"), ("populations", "populations")):
        for v in d.get(field, []):
            if v not in tax[vocab]:
                problems.append(f"{pid}: {field} value not in taxonomy: {v!r}")
    p = d.get("paper") or {}
    for k in PAPER_KEYS:
        if k not in p:
            problems.append(f"{pid}: paper missing {k}")
    if d.get("decision") == "INCLUDE":
        if p.get("doi") != inp["externalDoi"].lower():
            problems.append(f"{pid}: doi {p.get('doi')!r} != externalDoi")
        if d.get("doiMissing") is not False:
            problems.append(f"{pid}: doiMissing should be false")
        if not isinstance(p.get("year"), int):
            problems.append(f"{pid}: year not int")
        if str(p.get("year")) not in p.get("citation", ""):
            problems.append(f"{pid}: year not in citation")
        if p.get("year") != inp["crossrefYear"]:
            print(f"NOTE {pid}: year {p.get('year')} differs from crossrefYear {inp['crossrefYear']}")
    for s in walk_strings(d):
        if "—" in s:
            problems.append(f"{pid}: em dash found")
            break
    print(pid, d.get("decision"), d.get("studyDesign"), "|", d.get("populations"), "|", p.get("year"), p.get("doi"))

print("PROBLEMS:" if problems else "No problems found.")
for pr in problems:
    print(" -", pr)
sys.exit(1 if problems else 0)

